    done(null, {
      mid: reservation.id
    });
  },
  pay: function pay(business, reservation, paymentmethod, done) {
    var payment = reservation.payment;

    loadscript(function (err, IMP) {
      if (err) return done(err);

      var name = business.unitname ? business.name + ' ' + business.unitname + ' \uC608\uC57D' : business.name + ' \uC608\uC57D';

      var endpoint = _bookable2.default.endpoint();
      if (endpoint.endsWith('/')) endpoint = endpoint.substring(0, endpoint.length - 1);
      var m_redirect_url = endpoint + '/accommodation/' + reservation.aid + '/reservation/settlement/' + reservation.id + '?redirect=' + encodeURIComponent(paymentmethod.options.m_redirect_url);

      IMP.init(paymentmethod.options.cid);
      IMP.request_pay({
        name: name,
        amount: reservation.price,
        pg: paymentmethod.options.pg,
        pay_method: paymentmethod.options.method,
        merchant_uid: payment.options.mid,
        buyer_email: reservation.email,
        buyer_name: reservation.name,
        buyer_tel: reservation.mobile,
        buyer_addr: reservation.info && reservation.info.address,
        buyer_postcode: reservation.info && reservation.info.postcode,
        m_redirect_url: m_redirect_url
      }, function (response) {
        if (!response.success) return done(new Error('결제에 실패하였습니다.' + response.error_msg));
        done(null, response);
      });
    });
  }
};

